const principal='12345678-1234-1234-1234-123456789abc',key='22345678-1234-1234-1234-123456789abc',changeover='32345678-1234-1234-1234-123456789abc',release='42345678-1234-1234-1234-123456789abc',toRelease='52345678-1234-1234-1234-123456789abc',event='62345678-1234-1234-1234-123456789abc';
const target=()=>({deployment_no:'DEP-1',changeover_no:'CHANGEOVER-1'});
const context=()=>({...target(),changeover_id:changeover,from_release_id:release,to_release_id:toRelease,history_state:'IMPORTED',expected_revision:0,predecessor_id:null,changed_at:'2026-01-01T00:00:00.000000Z',note:'original note'});
const command=()=>({operation:'changeover-correction',target:target(),context:context(),body:{request_id:key,expected_revision:0,predecessor_id:null,from_release_id:release,changed_at:'2026-01-02T00:00:00.000000Z',note:null,correction_reason:'Correct mistaken time'}});
const eventNo=c=>'EVT-CC-'+c.body.request_id.replaceAll('-','');
const receipt=c=>({operation:c.operation,target:c.target,request_id:c.body.request_id,audit_event_no:eventNo(c),result:{changeover_id:c.context.changeover_id,changeover_no:c.target.changeover_no,from_release_id:c.body.from_release_id,to_release_id:c.context.to_release_id,changed_at:c.body.changed_at,note:c.body.note,correction_reason:c.body.correction_reason,revision:c.body.expected_revision+1,predecessor_id:c.body.predecessor_id}});
function audit(c,actor=principal){const {request_id,...request}=c.body,r=receipt(c).result;return{id:event,event_no:eventNo(c),actor_principal_id:actor,declared_actor_name:null,event_type:'CHANGEOVER',entity_type:'SOFTWARE_CHANGEOVER',entity_id:c.context.changeover_id,entity_ref:c.target.changeover_no,action:'CORRECTED',payload:{deployment_no:c.target.deployment_no,actor_source:'AUTHENTICATED_PRINCIPAL',correction_reason:c.body.correction_reason,request:{changeover_no:c.target.changeover_no,...request},before:{from_release_id:c.context.from_release_id,to_release_id:c.context.to_release_id,changed_at:c.context.changed_at,note:c.context.note},after:{from_release_id:r.from_release_id,to_release_id:r.to_release_id,changed_at:r.changed_at,note:r.note}}};}
module.exports={principal,key,changeover,release,toRelease,event,target,context,command,eventNo,receipt,audit};
